Lemma zh_cells_at : 0 < s -> forall k i st j, i <= j < i + Z.of_nat k ->
  (r_cells (get_shadow (zero_hdrs p s i k st) (fst p))) !! (snd p + UNIT + j * s - 4) = Some (0, s_tick st).
